using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Extensions.Hosting;

namespace Demo.Workers
{
    public class QueuePollingWorker : BackgroundService
    {
        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            while (!stoppingToken.IsCancellationRequested)
            {
                var batch = await FetchPendingAsync(stoppingToken);
                Console.WriteLine($"processing {batch} items");
                await Task.Delay(TimeSpan.FromSeconds(10), stoppingToken);
            }
        }

        private Task<int> FetchPendingAsync(CancellationToken token) => Task.FromResult(3);
    }
}

